from typing import Annotated
from fastapi import FastAPI, Depends, Response
from fastapi.testclient import TestClient
def modify_response(r: Response): r.headers['x']='1'
app=FastAPI()
@app.get('/')
def e(response: Annotated[Response, Depends(modify_response)]):
    return {'x': response.headers}
@app.get('/x')
def f(response: Response = Depends(modify_response)):
    return {'x': response.headers}
c=TestClient(app)
print(c.get('/').status_code, c.get('/').headers.get('x'), c.get('/x').headers.get('x'))
" && timeout 150 python -m pytest tests/test_dependency_class.py -q -x 2>&1 | tail -3

